const state = $ctrl.resources[key];
if (!state || state.loading) { return $ctrl.$q.when(false); }
state.loading = true;
state.error = null;
// Hide prior values during refresh/failure rather than present stale counts as current.
state.value = null;
if (key === 'pets') { $ctrl.featuredPets = []; }
if (key === 'countries') { $ctrl.continentCount = null; }
return $ctrl.$q.when().then(() => {
  if (key === 'inventory') { return $ctrl.petData.loadInventory(force === true); }
  if (key === 'pets') { return $ctrl.petData.loadPets('available', force === true); }
  return $ctrl.countryData.loadCountries(force === true);
}).then(value => {
  state.value = value;
  if (key === 'pets') {
    $ctrl.featuredPets = value.filter(pet => pet.status === 'available').slice(0, 3);
  }
  if (key === 'countries') {
    $ctrl.continentCount = new Set(value.map(country => country.continentCode).filter(Boolean)).size;
  }
  return true;
}).catch(err => {
  state.value = null;
  state.error = (err && err.message) || 'Unable to load this section. Please retry.';
  return false;
}).finally(() => {
  state.loading = false;
});

if ($ctrl.isBusy()) { return $ctrl.$q.when(false); }
$ctrl.refreshing = true;
return $ctrl.$q.all([
  $ctrl.loadResource('inventory', force),
  $ctrl.loadResource('pets', force),
  $ctrl.loadResource('countries', force)
]).then(results => {
  const complete = results.every(Boolean);
  if (force === true && complete) { $ctrl.lastSuccessfulRefresh = Date.now(); }
  return complete;
}).finally(() => {
  $ctrl.refreshing = false;
});

const state = $ctrl.resources[key === 'countries' ? 'countries' : 'inventory'];
if (state.loading || state.error || state.value === null) { return '—'; }
const value = key === 'countries' ? state.value.length : state.value[key];
return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value.toLocaleString() : '—';

const state = $ctrl.resources[key === 'countries' ? 'countries' : 'inventory'];
if (state.loading) { return 'Loading snapshot…'; }
if (state.error) { return 'Unavailable · retry below'; }
if (state.value === null) { return 'Not loaded yet'; }
if (key === 'countries') { return 'From the country directory'; }
return $ctrl.metricValue(key) === '—' ? 'Not reported by the demo API' : 'Reported demo inventory';

const state = $ctrl.resources.countries;
if (state.loading || state.error || state.value === null) { return 'Discover country names, capitals, languages and continents in one read-only directory.'; }
return state.value.length.toLocaleString() + ' countries across ' + $ctrl.continentCount.toLocaleString() + ' continents in the current dataset. Explore capitals, languages and more.';
